"""Regole pure della quota HofJ (RF-47, RF-48): limite effettivo, riserva, tetti, attesa stimata.

Limite effettivo = `limitPerMinute` meno un margine (chiave condivisa con altri client); la
classe `booking` ha una riserva garantita, `purchase` e `sync` si fermano prima di intaccarla.
Le percentuali passano da Decimal perché il floor su float sbaglia (100 × 0,29 = 28,999…).
"""
import math
from dataclasses import dataclass, replace
from datetime import datetime, timedelta
from decimal import ROUND_FLOOR, Decimal
from typing import Optional, Tuple

from vela.domain.models import QuotaClass

CALLS_PER_PURCHASE = 5   # RF-46: itinerario, customer, lettura pax, scrittura pax, totale


def _floor_share(value: int, share: float) -> int:
    return int((Decimal(value) * Decimal(str(share))).to_integral_value(rounding=ROUND_FLOOR))


def effective_limit(limit_per_minute: int, margin: float) -> int:
    return _floor_share(limit_per_minute, 1 - Decimal(str(margin)))


def booking_reserve(effective: int, reserve: float) -> int:
    return _floor_share(effective, reserve)


def cap_for(cls: QuotaClass, effective: int, reserve: int) -> int:
    """Chiamate che una classe può usare nella finestra: solo `booking` arriva al limite."""
    return effective if cls == QuotaClass.BOOKING else effective - reserve


def purchases_per_window(effective: int, reserve: int, calls_per_purchase: int = CALLS_PER_PURCHASE) -> float:
    budget = effective - reserve
    if budget <= 0:
        raise ValueError("nessun budget per gli acquisti: limite %d, riserva %d" % (effective, reserve))
    return budget / calls_per_purchase


def estimated_wait_seconds(position: int, per_window: float) -> int:
    """RF-48: posizione × 60 s ÷ acquisti per finestra, per eccesso. Nessun tetto."""
    return math.ceil(position * 60 / per_window)


def wait_minutes(seconds: int) -> int:
    """Minuti da dire al viaggiatore (RF-45): per eccesso, almeno 1."""
    return max(1, math.ceil(seconds / 60))


# --- Finestra di quota (RF-36..38, RF-47): stato puro, salvato dagli adapter -----------------

WINDOW = timedelta(seconds=60)


@dataclass(frozen=True)
class QuotaWindow:
    window_start: datetime
    window_end: datetime
    limit_per_minute: int
    used: int
    needs_refresh: bool


def fresh_window(now: datetime, limit_per_minute: int) -> QuotaWindow:
    """Finestra prima di ogni `GET /v1/quota`: parte dalla prima richiesta, da sincronizzare."""
    return QuotaWindow(now, now + WINDOW, limit_per_minute, 0, True)


def rolled(w: QuotaWindow, now: datetime) -> QuotaWindow:
    """Fa avanzare la finestra sulla griglia di 60 s ancorata da HofJ; `used` riparte da zero."""
    if now < w.window_end:
        return w
    skipped = int((now - w.window_end) // WINDOW)
    start = w.window_end + skipped * WINDOW
    return replace(w, window_start=start, window_end=start + WINDOW, used=0)


def caps(w: QuotaWindow, margin: float, reserve: float) -> Tuple[int, int]:
    effective = effective_limit(w.limit_per_minute, margin)
    return effective, booking_reserve(effective, reserve)


def try_acquire(w: QuotaWindow, cls: QuotaClass, n: int, now: datetime, margin: float,
                reserve: float, purchase_waiting: bool) -> Optional[QuotaWindow]:
    """Nuovo stato con `n` chiamate prenotate, o None: tutto il blocco o niente (RF-47)."""
    w = rolled(w, now)
    if cls == QuotaClass.SYNC and purchase_waiting:
        return None
    effective, res = caps(w, margin, reserve)
    if w.used + n > cap_for(cls, effective, res):
        return None
    return replace(w, used=w.used + n)


def after_429(w: QuotaWindow, now: datetime, margin: float, reserve: float) -> QuotaWindow:
    """RF-38: un 429 azzera il budget residuo della finestra e chiede una nuova lettura."""
    w = rolled(w, now)
    effective, _ = caps(w, margin, reserve)
    return replace(w, used=max(w.used, effective), needs_refresh=True)


def from_snapshot(limit_per_minute: int, used_in_window: int, started: datetime, ends: datetime) -> QuotaWindow:
    return QuotaWindow(started, ends, limit_per_minute, used_in_window, False)


def describe(w: QuotaWindow, now: datetime, margin: float, reserve: float) -> dict:
    """Vista per `/health` e per i test: la finestra corrente, senza modificarla."""
    w = rolled(w, now)
    effective, res = caps(w, margin, reserve)
    return {"limit_per_minute": w.limit_per_minute, "effective_limit": effective, "reserve": res,
            "used": w.used, "remaining": max(0, effective - w.used),
            "window_start": w.window_start, "window_end": w.window_end,
            "needs_refresh": w.needs_refresh}
"""Job di prenotazione (RF-23, RF-24, RF-51): chiude su HofJ un ordine pagato.

Una chiamata (`POST /v1/bookings`, classe di quota `booking`) che inoltra l'id del PaymentIntent
e lo stato del pagamento. Rete, timeout e 5xx: nuovo tentativo dopo 5, 10, 20, 40 secondi, poi
`booking_failed`. Un 4xx (prodotto o configurazione) non si ripete. Un 429 torna nella finestra
successiva senza contare il tentativo (RF-38). Un ordine che non è più `paid_pending_booking`
(già confermato da un altro job) chiude il job senza chiamate.
"""
from dataclasses import replace
from datetime import datetime, timedelta
from typing import Callable, Sequence

from vela.domain import say
from vela.domain.models import Job, JobStatus, Order, OrderStatus
from vela.domain.purchase import JobResult
from vela.ports.hofj import HofJRouter, PaymentProof, QuotaError, UpstreamError, HofJError
from vela.ports.repositories import Repositories

BOOKING_CALLS = 1


class BookingJob:
    def __init__(self, repos: Repositories, hofj: HofJRouter, now: Callable[[], datetime],
                 max_attempts: int = 5, backoff: Sequence[int] = (5, 10, 20, 40)):
        self.repos, self.hofj, self.now = repos, hofj, now
        self.max_attempts, self.backoff = max_attempts, tuple(backoff)

    def run(self, job: Job, next_window: datetime) -> JobResult:
        order = self.repos.orders.get(job.order_id)
        if order is None or order.status != OrderStatus.PAID_PENDING_BOOKING:
            return self._close(job, JobStatus.DONE)
        proof = PaymentProof(order.payment_ref or "", "succeeded")
        try:   # RF-56: brand del prodotto dell'ordine, riletto a ogni esecuzione
            hofj = self.hofj.client_for(self.repos.products.get(order.product_id))
            code = hofj.create_booking(order.itinerary_id, proof)
        except QuotaError as exc:
            return JobResult(self._pending(job, next_window, exc, job.attempts), hit_429=True)
        except UpstreamError as exc:
            attempts = job.attempts + 1
            if attempts >= self.max_attempts:
                self._fail(order, "booking_upstream")
                return self._close(replace(job, attempts=attempts), JobStatus.DEAD, exc)
            wait = self.backoff[min(attempts, len(self.backoff)) - 1]
            return JobResult(self._pending(job, self.now() + timedelta(seconds=wait), exc, attempts))
        except HofJError as exc:
            self._fail(order, "booking_rejected")
            return self._close(job, JobStatus.DEAD, exc)
        self._save(replace(order, status=OrderStatus.CONFIRMED, booking_code=code))
        return self._close(job, JobStatus.DONE)

    def _save(self, order: Order) -> None:
        self.repos.orders.save(replace(order, updated_at=self.now()))

    def _fail(self, order: Order, reason: str) -> None:
        intent = self.repos.intents.get(order.intent_id)
        lang = intent.criteria.language if intent else "it"
        self._save(replace(order, status=OrderStatus.BOOKING_FAILED,
                           failure_reason=say.failure_reason(reason, lang)))

    def _pending(self, job: Job, run_after: datetime, exc: Exception, attempts: int) -> Job:
        job = replace(job, status=JobStatus.PENDING, run_after=run_after, locked_at=None,
                      attempts=attempts, last_error=_describe(exc))
        self.repos.jobs.save(job)
        return job

    def _close(self, job: Job, status: JobStatus, exc: Exception = None) -> JobResult:
        job = replace(job, status=status, locked_at=None,
                      last_error=_describe(exc) if exc is not None else job.last_error)
        self.repos.jobs.save(job)
        return JobResult(job)


def _describe(exc: Exception) -> str:
    return ("%s: %s" % (type(exc).__name__, exc))[:500]
"""Configurazione di Vela, letta solo da variabili d'ambiente (spec §6).

Nessun file viene aperto: i segreti arrivano dall'ambiente del processo.
"""
import os
from dataclasses import dataclass
from typing import Dict, Mapping, Optional, Tuple

DEFAULT_UPSTREAM_MODE = "replay"
BRAND_SPORTS = ("padel", "tennis")


def normalize_database_url(url: Optional[str]) -> Optional[str]:
    """Riscrive lo schema Postgres nella forma che SQLAlchemy 2 + psycopg 3 richiedono.

    Render fornisce ``postgres://``; ``postgresql://`` senza driver userebbe psycopg2.
    Tutto il resto (``sqlite://``, driver già esplicito) resta invariato.
    """
    if url is None:
        return None
    for prefix in ("postgres://", "postgresql://"):
        if url.startswith(prefix):
            return "postgresql+psycopg://" + url[len(prefix):]
    return url


def parse_brands(raw: str) -> Dict[str, str]:
    """`HOFJ_BRANDS` ("padel=weebora.com,tennis=terrarossa.com") → {sport: brand}.

    Sport in {padel, tennis}, uno per voce, brand distinti, almeno una voce (decisione M10).
    Ogni errore è un `ValueError` con il motivo: l'app non parte.
    """
    brands: Dict[str, str] = {}
    for entry in (part.strip() for part in raw.split(",")):
        if not entry:
            continue
        if "=" not in entry:
            raise ValueError("HOFJ_BRANDS: voce %r non nel formato sport=brand" % entry)
        sport, brand = (side.strip() for side in entry.split("=", 1))
        if sport not in BRAND_SPORTS:
            raise ValueError("HOFJ_BRANDS: sport %r sconosciuto, ammessi %s"
                             % (sport, ", ".join(BRAND_SPORTS)))
        if not brand:
            raise ValueError("HOFJ_BRANDS: brand vuoto per %s" % sport)
        if sport in brands:
            raise ValueError("HOFJ_BRANDS: sport %s ripetuto" % sport)
        if brand in brands.values():
            raise ValueError("HOFJ_BRANDS: brand %s usato per due sport" % brand)
        brands[sport] = brand
    if not brands:
        raise ValueError("HOFJ_BRANDS: serve almeno una voce sport=brand")
    return brands


@dataclass(frozen=True)
class Settings:
    database_url: Optional[str] = None
    hofj_api_key: Optional[str] = None
    hofj_base_url: Optional[str] = None
    hofj_brands: Optional[str] = None                  # M10: "padel=weebora.com,tennis=…"
    hofj_brand: Optional[str] = None                   # pre-M10: letta solo per dire di migrare
    stripe_secret_key: Optional[str] = None
    stripe_webhook_secret: Optional[str] = None
    vela_api_token: Optional[str] = None
    vela_upstream_mode: str = DEFAULT_UPSTREAM_MODE
    anthropic_api_key: Optional[str] = None
    vela_public_url: Optional[str] = None
    # Parametri di M5: configurabili da codice, mai da env (l'elenco di §6 resta chiuso).
    worker_concurrency: int = 4                        # RF-50, thread per istanza
    quota_margin: float = 0.10                         # limite effettivo = limitPerMinute × 0,9
    booking_reserve: float = 0.20                      # RF-47, quota della finestra per i booking
    purchase_max_attempts: int = 3                     # RF-46
    booking_max_attempts: int = 5                      # RF-24
    booking_backoff: Tuple[int, ...] = (5, 10, 20, 40)  # secondi tra i tentativi di booking
    job_lease_seconds: int = 120                       # un job running più vecchio torna prelevabile
    payment_poll_seconds: int = 60                     # RF-20, verifica della Checkout Session
    replay_latency: Tuple[float, float] = (0.0, 0.0)   # replay: latenza simulata min/max (M13)
    replay_limit: Optional[int] = None                 # replay: quota simulata, None = illimitata

    @classmethod
    def from_env(cls, environ: Optional[Mapping[str, str]] = None) -> "Settings":
        env = os.environ if environ is None else environ
        return cls(
            database_url=normalize_database_url(env.get("DATABASE_URL")),
            hofj_api_key=env.get("HOFJ_API_KEY"),
            hofj_base_url=env.get("HOFJ_BASE_URL"),
            hofj_brands=env.get("HOFJ_BRANDS"),
            hofj_brand=env.get("HOFJ_BRAND"),
            stripe_secret_key=env.get("STRIPE_SECRET_KEY"),
            stripe_webhook_secret=env.get("STRIPE_WEBHOOK_SECRET"),
